/* ============================================================
   أطياب الجاسم (React) — بطاقة شركة توصيل (CarrierCard)

   بطاقة واحدة لكل شركة من /api/shipping-carriers بنفس لغة بطاقات
   الديمو: اسم الشركة + سعر التوصيل (بعملة المتجر) + الهاتف
   (رابط اتصال) + البريد (رابط مراسلة). الحقول الغائبة تُخفى.
   ★ كل الأيقونات بمقاس inf-ico (20px) — بلا SVG حرّ يكبُر ويكسر الصفحة.
   ============================================================ */

import { useAppSelector } from "../../redux/hooks.js";
import { selectStoreSettings } from "../../redux/slices/settingsSlice.js";
import { Icon } from "../Source/Icons.jsx";

function group(n) {
  return String(n).replace(/\B(?=(\d{3})+(?!\d))/g, ",");
}

export default function CarrierCard(props) {
  const c = props.carrier || {};
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const settings = useAppSelector(selectStoreSettings);
  const isEn = language === "en";
  const currency = (settings && settings.defaultCurrencyCode) || "AED";
  const name = c.name || (isEn ? "Delivery carrier" : "شركة توصيل");
  const priceText = c.price != null ? group(c.price) + " " + currency : "";

  return (
    <article className="inf-country">
      <header className="inf-country-head">
        <Icon name="truck" className="inf-ico inf-ico--gold" strokeWidth={1.7} />
        <h3>{name}</h3>
      </header>
      <ul className="inf-carriers">
        <li className="inf-carrier">
          <div className="inf-carrier-top">
            <h4>{isEn ? "Delivery service" : "خدمة توصيل"}</h4>
            {priceText ? <span className="inf-tag">{priceText}</span> : null}
          </div>
          <dl className="inf-carrier-meta">
            {priceText ? (
              <div>
                <dt>{isEn ? "Fee" : "السعر"}</dt>
                <dd>{priceText}</dd>
              </div>
            ) : null}
            {c.phone ? (
              <div>
                <dt>{isEn ? "Phone" : "الهاتف"}</dt>
                <dd dir="ltr">
                  {c.phoneHref ? <a href={c.phoneHref}>{c.phone}</a> : c.phone}
                </dd>
              </div>
            ) : null}
            {c.email ? (
              <div>
                <dt>{isEn ? "Email" : "البريد"}</dt>
                <dd dir="ltr">
                  <a href={"mailto:" + c.email}>{c.email}</a>
                </dd>
              </div>
            ) : null}
          </dl>
        </li>
      </ul>
    </article>
  );
}
