/* ============================================================
   أطياب الجاسم (React) — بطاقة شركة التوصيل (DeliveryCard)

   تعرض دولة + ملاحظتها + شركات الشحن الثلاث فيها (الاسم، المدة،
   التغطية، الوصف، الموقع) — نفس بطاقة صفحة «طرق التوصيل».
   ★ البيانات من ATYAB_CARRIERS في ملف البيانات (تُمرَّر كـ prop).
   ============================================================ */

import { T } from "../../i18n.js";
import { useAppSelector } from "../../redux/hooks.js";
import { Flag, Icon } from "../Source/Icons.jsx";

export default function DeliveryCard(props) {
  const country = props.country;
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const isEn = language === "en";
  if (!country) return null;

  return (
    <article className="inf-country">
      <header className="inf-country-head">
        <span className="inf-country-flag">
          <Flag code={country.flag} />
        </span>
        <h3>{T(country.country, language)}</h3>
      </header>

      {country.note ? <p className="inf-country-note">{T(country.note, language)}</p> : null}

      <ul className="inf-carriers">
        {(country.companies || []).map(function (co, i) {
          return (
            <li className="inf-carrier" key={i}>
              <div className="inf-carrier-top">
                <h4>{isEn && co.en ? co.en : co.name}</h4>
                {co.tag ? <span className="inf-tag">{T(co.tag, language)}</span> : null}
              </div>
              <dl className="inf-carrier-meta">
                <div>
                  <dt>{isEn ? "Delivery time" : "المدة"}</dt>
                  <dd>{T(co.days, language)}</dd>
                </div>
                <div>
                  <dt>{isEn ? "Coverage" : "التغطية"}</dt>
                  <dd>{T(co.coverage, language)}</dd>
                </div>
              </dl>
              {co.desc ? <p>{T(co.desc, language)}</p> : null}
              {co.site ? (
                <span className="inf-site" dir="ltr">
                  {co.site}
                </span>
              ) : null}
            </li>
          );
        })}
      </ul>

      {props.trackingHint ? (
        <p className="inf-foot-note">
          <Icon name="info" strokeWidth={1.8} />
          <span>{props.trackingHint}</span>
        </p>
      ) : null}
    </article>
  );
}
