/* ============================================================
   أطياب الجاسم (React) — صفحة طرق التوصيل (DeliveryPage)

   تستدعي: DeliveryCard مرة لكل دولة (بطاقة تعرض الدولة وشركات الشحن فيها
   وكل معلوماتها المهمة) **أولاً**، ثم DeliveryInfo (الرسوم · المدة ·
   خطوات تتبّع الشحنة).

   ★ النصوص من ATYAB_INFO_PAGES.shipping وقائمة الدول من الخادم —
     لا نصّ مكتوب هنا.
   ★ قائمة الدول/الشركات من الخادم وحده (storeInfo.shipping) — بلا أي
     احتياط مضمّن: تحميل ← سكيلتون، فراغ ← رسالة نصية.
   ============================================================ */

import { useEffect } from "react";
import { usePageMeta } from "../usePageMeta.js";
import { ATYAB_INFO_PAGES } from "../data/appConfig.js";
import { T } from "../i18n.js";
import { useAppDispatch, useAppSelector } from "../redux/hooks.js";
import { loadStoreSection } from "../redux/slices/storeInfoSlice.js";
import DeliveryInfo from "../components/UserExperience/DeliveryInfo.jsx";
import DeliveryCard from "../components/UserExperience/DeliveryCard.jsx";
import CarrierCard from "../components/UserExperience/CarrierCard.jsx";
import { CarrierSkeleton } from "../components/Skeletons/index.js";
import { Icon } from "../components/Source/Icons.jsx";

export default function DeliveryPage() {
  const dispatch = useAppDispatch();
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const live = useAppSelector(function (s) {
    return s.storeInfo.shipping;
  });
  const page = (ATYAB_INFO_PAGES && ATYAB_INFO_PAGES.shipping) || {};

  /* ★ الجلب من الخادم مرة واحدة لكل زيارة (الشريحة تتذكّر ما وصل) */
  useEffect(
    function () {
      dispatch(loadStoreSection("shipping"));
    },
    [dispatch]
  );

  const fetched = live && Array.isArray(live.items) ? live.items : [];
  /* ★ شكلان: مجموعات دول (قديم) أو قائمة شركات مسطّحة من /api/shipping-carriers */
  const isFlat = !!(fetched.length && fetched[0] && fetched[0].kind === "carrier");
  const countries = isFlat ? [] : fetched;
  const carriers = isFlat ? fetched : [];
  const loading = !!(live && live.status === "loading") && !countries.length;
  const empty = !loading && !countries.length && !carriers.length;

  usePageMeta({
    route: "info",
    titleAr: T(page.title, "ar"),
    titleEn: T(page.title, "en")
  });

  return (
    <section className="container view inf" id="infoView">
      <header className="inf-hero">
        {page.eyebrow ? <span className="inf-eyebrow">{T(page.eyebrow, language)}</span> : null}
        <h1 className="inf-h1">
          {T(page.title, language)} <span className="gold-text">{T(page.titleGold, language)}</span>
        </h1>
        {page.lead ? <p className="inf-lead">{T(page.lead, language)}</p> : null}
      </header>

      <div className="inf-body">
        {/* ★ الدول وشركات الشحن أولاً (كما طُلب): يرى العميل الشركات
           المتاحة في بلده قبل الحديث عن الرسوم والمدة والتتبّع. */}
        <section className="inf-block">
          <h2 className="inf-h2">
            <Icon name="globe" className="inf-ico inf-ico--gold" strokeWidth={1.7} />
            {language === "en" ? "Countries & carriers" : "الدول وشركات الشحن"}
          </h2>
          {loading ? (
            <CarrierSkeleton count={3} />
          ) : (
            <div className="inf-countries">
              {countries.map(function (country, i) {
                return <DeliveryCard country={country} key={(country.flag || country.key || "c") + i} />;
              })}
              {carriers.map(function (co, i) {
                return <CarrierCard carrier={co} key={(co.id || "c") + "-" + i} />;
              })}
            </div>
          )}
          {empty ? (
            <div className="inf-state" role="status">
              <Icon name="info" className="inf-ico inf-ico--gold" strokeWidth={1.7} />
              <span>{language === "en" ? "No carriers published yet." : "لم تُنشر شركات الشحن بعد."}</span>
            </div>
          ) : null}
        </section>

        <div className="inf-block">
          <DeliveryInfo showNote={false} />
        </div>
      </div>
    </section>
  );
}
