/* ============================================================
   أطياب الجاسم (React) — معلومات التوصيل (DeliveryInfo)

   الرسوم والمُدّة + خطوات تتبّع الشحنة + ملاحظة الصفحة.
   ★ كل النصوص من ATYAB_INFO_PAGES.shipping في ملف البيانات
     (قسم facts وقسم steps) — فلا نصّ مكرّر هنا.
   ============================================================ */

import { Link } from "react-router-dom";
import { pathForPage } from "../../routes.js";
import { ATYAB_INFO_PAGES, ATYAB_INFO_NOTE, ATYAB_PAGES } from "../../data/appConfig.js";
import { T } from "../../i18n.js";
import { useAppSelector } from "../../redux/hooks.js";
import { Icon } from "../Source/Icons.jsx";

function sectionsOf(page) {
  return (page && page.sections) || [];
}

export default function DeliveryInfo(props) {
  const language = useAppSelector(function (s) {
    return s.ui.language;
  });
  const page = ATYAB_INFO_PAGES && ATYAB_INFO_PAGES.shipping;
  const sections = sectionsOf(page);
  const facts = sections.filter(function (s) {
    return s.kind === "facts";
  })[0];
  const steps = sections.filter(function (s) {
    return s.kind === "steps";
  })[0];
  const note = ATYAB_INFO_NOTE;

  return (
    <div className="inf-body">
      {facts ? (
        <section className="inf-block">
          <h2 className="inf-h2">{T(facts.title, language)}</h2>
          <ul className="inf-facts">
            {(facts.items || []).map(function (item, i) {
              return (
                <li key={i}>
                  <Icon name={item.icon} className="inf-ico inf-ico--gold" />
                  <span className="inf-fact-label">{T(item.label, language)}</span>
                  <b className="inf-fact-value">{T(item.value, language)}</b>
                </li>
              );
            })}
          </ul>
        </section>
      ) : null}

      {steps ? (
        <section className="inf-block">
          <h2 className="inf-h2">{T(steps.title, language)}</h2>
          <ol className="inf-steps">
            {(steps.items || []).map(function (item, i) {
              return (
                <li key={i}>
                  {item && item.to ? (
                    <Link to={pathForPage(item.to, ATYAB_PAGES)}>
                      <span>{T(item, language)}</span>
                    </Link>
                  ) : (
                    <span>{T(item, language)}</span>
                  )}
                </li>
              );
            })}
          </ol>
        </section>
      ) : null}

      {props.showNote !== false && note ? (
        <p className="inf-foot-note">
          <Icon name="spark" strokeWidth={1.6} />
          <span>{T(note, language)}</span>
        </p>
      ) : null}
    </div>
  );
}
